if(!$PCC->auditReady()):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-stream"></i><strong>Audit V3 non installé</strong><span>Applique la migration 2026_08_22_paradise_control_center_v3.sql pour activer le journal.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$staff=trim((string)($_GET['staff']??''));$module=trim((string)($_GET['module']??''));$action=trim((string)($_GET['action_type']??''));$page=max(1,(int)($_GET['p']??1));$per=50;$where=array('1=1');$types='';$params=array();if($q!==''){$like='%'.mb_substr($q,0,80).'%';$where[]='(target_id LIKE ? OR reason LIKE ? OR target_type LIKE ?)';$types.='sss';$params[]=$like;$params[]=$like;$params[]=$like;}if($staff!==''){$where[]='staff_username=?';$types.='s';$params[]=$staff;}if($module!==''){$where[]='module=?';$types.='s';$params[]=$module;}if($action!==''){$where[]='action=?';$types.='s';$params[]=$action;}$count=$DB->PreparedRow('SELECT COUNT(*) total FROM cms_admin_audit_log WHERE '.implode(' AND ',$where),$types,$params);$total=$count?(int)$count['total']:0;$pages=max(1,(int)ceil($total/$per));if($page>$pages)$page=$pages;$offset=($page-1)*$per;$rows=$DB->PreparedAll('SELECT * FROM cms_admin_audit_log WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT '.$per.' OFFSET '.(int)$offset,$types,$params);$staffs=$DB->PreparedAll('SELECT DISTINCT staff_username FROM cms_admin_audit_log ORDER BY staff_username');$modules=$DB->PreparedAll('SELECT DISTINCT module FROM cms_admin_audit_log ORDER BY module');$actions=$DB->PreparedAll('SELECT DISTINCT action FROM cms_admin_audit_log ORDER BY action');$link=function($p)use($q,$staff,$module,$action){return URL.'/admin.php?'.http_build_query(array('page'=>'logs','q'=>$q,'staff'=>$staff,'module'=>$module,'action_type'=>$action,'p'=>$p));};
?>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="logs"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Cible, ID, raison…"></div><select name="staff" class="pcc-select-compact"><option value="">Tous staffs</option><?php foreach($staffs as $s):?><option <?php echo $staff===$s['staff_username']?'selected':'';?>><?php echo $h($s['staff_username']);?></option><?php endforeach;?></select><select name="module" class="pcc-select-compact"><option value="">Tous modules</option><?php foreach($modules as $m):?><option <?php echo $module===$m['module']?'selected':'';?>><?php echo $h($m['module']);?></option><?php endforeach;?></select><select name="action_type" class="pcc-select-compact"><option value="">Toutes actions</option><?php foreach($actions as $a):?><option <?php echo $action===$a['action']?'selected':'';?>><?php echo $h($a['action']);?></option><?php endforeach;?></select><button class="pcc-button secondary">Filtrer</button><span class="pcc-filter-count"><?php echo $number($total);?> log(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Date</th><th>Staff</th><th>Module</th><th>Action</th><th>Cible</th><th>Raison</th><th>IP</th><th>Avant / après</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="pcc-empty compact"><strong>Aucun log trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?php echo $h($PCC->formatDate($r['created_at']));?></td><td><strong><?php echo $h($r['staff_username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['staff_id'];?></small></td><td><span class="pcc-badge"><?php echo $h($r['module']);?></span></td><td><code><?php echo $h($r['action']);?></code></td><td><?php echo $h($r['target_type']);?> <?php echo $r['target_id']!==null?'#'.$h($r['target_id']):'';?></td><td><span class="pcc-log-reason"><?php echo $h($r['reason']);?></span></td><td><code><?php echo $h($r['ip_address']??'—');?></code></td><td><details class="pcc-diff-details"><summary>Diff</summary><div class="pcc-diff"><pre><?php echo $h($r['before_data']??'—');?></pre><pre><?php echo $h($r['after_data']??'—');?></pre></div></details></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):?><div class="pcc-pagination"><?php if($page>1):?><a href="<?php echo $h($link($page-1));?>">‹</a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?php echo $i===$page?'is-active':'';?>" href="<?php echo $h($link($i));?>"><?php echo $i;?></a><?php endfor;?><?php if($page<$pages):?><a href="<?php echo $h($link($page+1));?>">›</a><?php endif;?></div><?php endif;?></section>
